const D = { fr: orgFr as Record<OrgKey, string>, en: orgEn };
export type OrgT = (key: OrgKey, vars?: Record<string, string | number>) => string;

export function orgTranslate(lang: "fr" | "en", key: OrgKey, vars?: Record<string, string | number>): string {
  const s = D[lang][key] ?? orgEn[key] ?? key;
  return vars ? s.replace(/\{(\w+)\}/g, (m, k: string) => (k in vars ? String(vars[k]) : m)) : s;
}

export function useOrgT(): OrgT {
  const { lang } = useUI();
  return useCallback((key: OrgKey, vars?: Record<string, string | number>) => orgTranslate(lang, key, vars), [lang]);
}
